import java.util.*;

public class Main {
    String removeDuplicates(String s) {
        boolean changed = true;
        while (changed) {                                                            // keep repeating until a full pass finds nothing to remove
            changed = false;
            for (int i = 0; i < s.length() - 1; i++) {
                if (s.charAt(i) == s.charAt(i + 1)) {                                     // found an adjacent duplicate pair
                    s = s.substring(0, i) + s.substring(i + 2);                               // remove both characters
                    changed = true;
                    break;
                }
            }
        }
        return s;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.removeDuplicates("abbaca"));
    }
}

