#include <bits/stdc++.h>
using namespace std;

string removeDuplicates(string s) {
    bool changed = true;
    while (changed) {                                                                  // keep repeating until a full pass finds nothing to remove
        changed = false;
        for (int i = 0; i + 1 < (int)s.size(); i++) {
            if (s[i] == s[i + 1]) {                                                         // found an adjacent duplicate pair
                s.erase(i, 2);                                                                 // remove both characters
                changed = true;
                break;
            }
        }
    }
    return s;
}

int main() {
    cout << removeDuplicates("abbaca") << endl;
    return 0;
}

