string removeDuplicates(string s) {
    string stack;                                                                          // using the string itself as a stack (push_back/pop_back)
    for (char c : s) {
        if (!stack.empty() && stack.back() == c) {
            stack.pop_back();                                                                // this character cancels out with the top of the stack
        } else {
            stack.push_back(c);                                                                 // no match: this character survives (for now)
        }
    }
    return stack;
}

